const activities=[
{id:0,name:'Whale watching',place:'Long Wharf · departure',price:85.56,lat:42.3591,lng:-71.0504,image:'scene-0.webp',time:'3–4 hours',line:'Out to sea, into a whale’s world.',detail:'Cruise to offshore feeding grounds with an Aquarium naturalist. Watch for humpbacks surfacing and learn how to recognize their behavior.',includes:['Offshore boat trip','Live naturalist narration','Marine wildlife watching'],why:'Your ticket pays for the boat, crew and guided offshore experience.',moment:'A whale surfaces beside the boat. Your ticket brought you out to its ocean habitat.',priceBasis:'Previous prototype budget figure; live fare not verified. Wildlife appearances in this game are scripted.'},
{id:1,name:'Lobster feast',place:'Long Wharf · waterfront dining',price:73,lat:42.3592,lng:-71.0526,image:'scene-1.webp',time:'Allow 60–90 min',line:'Crack the shell. Make a meal of it.',detail:'Sit down by the waterfront for a whole-lobster meal. Take your time cracking the claws and enjoying a special Boston food experience.',includes:['Whole-lobster meal','A sit-down restaurant experience'],why:'Here you’re buying a special meal, rather than a tour or admission.',moment:'The lobster arrives at your table. You chose to make the meal a highlight of your day.',priceBasis:'Previous prototype meal allowance, not a verified current restaurant quote. The map shows the dining area, not a booked venue.'},
{id:2,name:'Campus adventure',place:'Harvard Yard · Cambridge',price:0,lat:42.3745,lng:-71.1172,image:'scene-2.webp',time:'Allow 30–45 min',line:'Follow your curiosity through the courtyard.',detail:'Wander the red-brick paths and leafy courtyards. Find your favorite building and imagine what you might study one day.',includes:['Self-guided outdoor walk','Courtyard photo stops'],why:'You explore public outdoor spaces yourself; no guide or indoor admission is included.',moment:'You find a quiet corner among the red-brick buildings. Curiosity doesn’t need an admission ticket.',priceBasis:'Outdoor self-guided visit; campus access can vary.'},
{id:3,name:'Harbor wander',place:'Harborwalk · Christopher Columbus Park',price:0,lat:42.3615,lng:-71.0501,image:'scene-3.webp',time:'Allow 30–45 min',line:'Front-row seats to the harbor.',detail:'Walk beside the water, watch the boats and find a skyline photo spot. Enjoy the sea air while staying on shore.',includes:['Waterfront walk','Boats and skyline views'],why:'A public waterfront is free to explore. You’re watching from shore, not taking a boat tour.',moment:'Sailboats drift past the waterfront. A lovely view, and your money stays in your wallet.',priceBasis:'Public outdoor walk.'},
{id:4,name:'Old North discovery',place:'Old North Church · North End',price:10,lat:42.3663,lng:-71.0545,image:'north.webp',time:'Allow 45–60 min',line:'Two lanterns. A trail of clues.',detail:'Explore the historic church and crypt, listen to its stories and follow a family scavenger hunt.',includes:['Sanctuary & crypt entry','Audio guide','Family scavenger hunt'],why:'Your Discovery Pass adds indoor access and activities to an ordinary walk.',moment:'You follow the clues through Old North. Your ticket opened a door to a different kind of adventure.',priceBasis:'Discovery Pass adult rate (13+); ages 6–12 have a lower rate.',source:'https://oldnorth.com/visit/'},
{id:5,name:'Freedom Trail stories',place:'Faneuil Hall · tour start',price:15,lat:42.3601,lng:-71.0568,image:'trail.webp',time:'90 minutes',line:'The red-brick trail has stories to tell.',detail:'Follow a guide on the Walk Into History tour, discovering stories connected to 11 historic sites along the route.',includes:['Live guided walk','90 minutes of stories','11 historic sites highlighted'],why:'The trail itself is free; this ticket buys a guide’s knowledge and storytelling.',moment:'Your guide brings the street’s history to life. You paid for the stories, not just the walk.',priceBasis:'Published student rate; the game uses a 14-year-old student. Online booking fees, if any, are excluded.',source:'https://www.thefreedomtrail.org/tours/walk-history-faneuil-hall'},
{id:6,name:'City-to-river Duck Tour',place:'Museum of Science · departure',price:59.85,lat:42.3677,lng:-71.0711,image:'duck.webp',time:'80 minutes',line:'A city ride that splashes into the river.',detail:'Ride through Boston with a live guide, then enter the Charles River in the same amphibious vehicle for a water-level city view.',includes:['Land & river ride','Live tour narration','80-minute experience'],why:'One ticket combines a guided city ride and a river experience.',moment:'Splash! Your vehicle becomes a boat. You get to see Boston from two different perspectives.',priceBasis:'2026 adult rate $57 + mandatory 5% fee = $59.85 at the booth. Online booking adds $2.',source:'https://bostonducktours.com/on-sale/individual-rates/'}
];
const initial=()=>({stage:'intro',intro:0,events:[],pendingChoice:null,lessonIndex:0,wishes:[],plan:[],initialSave:20,save:20,trip:0,photos:[],learn:false,invited:false});let s=initial();const app=document.querySelector('#app'),modal=document.querySelector('#modal');const money=n=>'$'+n.toFixed(2).replace(/\.00$/,'');const sum=()=>Math.round(s.plan.reduce((a,id)=>a+activities[id].price,0)*100)/100;const art=(id,cl='')=>`<img class="art art-${id} ${cl}" src="assets/${activities[id].image}" alt="${activities[id].name}, illustrated with our rabbit traveler">`;
function header(){const names=['Make a wish','Your wallet','Plan your day','Go explore','Bring it home'];const current=['wish','wallet','plan','trip','end'].indexOf(s.stage);return `<header class="top"><div class="brand">Bunny’s Boston Day <span style="font-family:sans-serif;font-size:12px">✦</span></div><nav class="steps" aria-label="Game progress">${names.map((n,i)=>`<span class="step ${current===i?'active':''}">${i+1}. ${n}</span>`).join('')}</nav></header>`}
function footer(){return `<footer class="footer"><span>A little adventure in spending & saving · Ages 12–15</span><span><button class="textbtn" onclick="priceNote()">About these prices</button> <button class="textbtn" onclick="restart()">Start again</button></span></footer>`}
function map(){return `<div class="map" aria-label="Illustrated activity map, schematic locations"><div class="land"></div><div class="river"></div><div class="road"></div><span class="maplabel">BOSTON HARBOR</span>${activities.map(a=>{const selected=(s.stage==='wish'?s.wishes:s.plan).includes(a.id);const unavailable=s.stage==='plan'&&!selected&&sum()+a.price>100;return `<button class="pin ${selected?'selected':''} ${unavailable?'unavailable':''}" style="left:${a.x}%;top:${a.y}%" onclick="openActivity(${a.id})" aria-label="Explore ${a.name}${s.stage==='plan'?', '+money(a.price):''}">${art(a.id)}<strong>${a.name}</strong>${selected?'<span class="tag">♥</span>':s.stage==='plan'?`<span class="tag">${a.price?money(a.price):'FREE'}</span>`:''}</button>`}).join('')}<span class="mapnote">An illustrated map, not to scale</span></div>`}
function budget(){const spent=sum(),remaining=100-spent;return `<div class="budget"><div><span class="small">Day’s plan</span><strong>${money(spent)}</strong></div><div class="grow"><span class="small">Your $100</span><div class="bar"><span class="spent" style="width:${spent}%"></span><span class="saved" style="width:${remaining}%"></span></div></div><div><span class="small">Left for later</span><strong>${money(remaining)}</strong></div></div>`}
function rows(ids,editable=false){return ids.map((id,i)=>`<div class="wishrow">${art(id,'thumb')}<div>${editable?`${i+1}. `:''}${activities[id].name}${editable?`<br><span class="small">${money(activities[id].price)}</span>`:''}</div>${editable?`<button class="remove" onclick="removePlan(${id})" aria-label="Remove ${activities[id].name}">×</button>`:''}</div>`).join('')}
function render(){if(s.stage==='intro'){renderIntro();return}let content='';if(s.stage==='wish')content=`<div><div class="eyebrow">Bonnie’s notebook · Tomorrow’s wishes</div><h1>Boston is calling.<br>What’s on your wishlist?</h1><p class="muted" style="margin-top:10px">Tap a place. Take a peek. Save the experiences you love.</p></div><div class="layout">${map()}<aside class="notebook"><div class="eyebrow">My travel notebook</div><h2>A day to dream of</h2><div class="wishes">${s.wishes.length?rows(s.wishes):'<div class="empty">Your first wish is waiting.<br><span class="small">Explore a picture on the map.</span></div>'}</div><span class="small">${s.wishes.length} wishes · Pick as many as you like</span><button style="margin-top:14px" class="primary" ${!s.wishes.length?'disabled':''} onclick="setStage('wallet')">Let’s check my wallet</button></aside></div>`;
if(s.stage==='wallet')content=`<section class="walletstage"><div class="eyebrow">The night before · A gift from Mom</div><h1>“Here’s $100 for your adventure.”</h1><p style="margin-top:15px">A day in Boston. A summer reunion with your cousin. What will you keep for each?</p><div class="walletintro"><img src="assets/home.webp" alt="Mom gives Bunny money for tomorrow"><div><div class="eyebrow">A note from your cousin</div><p>“When you visit Amsterdam next summer, let’s cycle along the canals and find our favorite bakery!”</p><button class="textbtn" onclick="showInvitation()">Open the postcard again</button></div></div><div class="wallet"><div class="pocket"><div class="eyebrow">Spend tomorrow</div><h3>My Boston day</h3><div class="bigmoney" id="spendmoney">${money(100-s.save)}</div><div class="bills" id="bills">${bills(100-s.save)}</div></div><div class="pocket"><div class="eyebrow">Save for later</div><h3>Summer with my cousin</h3><img class="pocketphoto" src="assets/europe.webp" alt="Two rabbit cousins cycling beside a canal"><div class="bigmoney" id="savemoney">${money(s.save)}</div><span class="small">Towards our Europe trip, one little bit at a time</span></div></div><label for="savings"><strong>How much would you like to set aside?</strong></label><input class="range" type="range" id="savings" min="0" max="100" step="5" value="${s.save}" oninput="setSavings(+this.value)"><div class="rangeLabels"><span>$0 for later</span><span>$100 for later</span></div>${bird('Saving keeps some of today’s money for a future experience you care about. You can adjust your plan before leaving.')}<div class="actions"><button class="secondary" onclick="setStage('wish')">Back to my wishes</button><button class="primary" onclick="beginPlan()">Plan my Boston day</button></div></section>`;
if(s.stage==='plan')content=`<div class="eyebrow">Make room for what matters</div><h1>Your money. Your kind of day.</h1><p class="muted" style="margin-top:9px">Choose 2–4 stops. Tap any place to compare, add, or swap.</p>${budget()}<div class="layout">${map()}<aside class="notebook"><div class="eyebrow">My itinerary · ${s.plan.length}/4 stops</div><h2>One lovely day</h2><div class="wishes">${s.plan.length?rows(s.plan,true):'<div class="empty">Where shall we go first?<br><span class="small">Your wishlist places have a heart in their previews.</span></div>'}</div><div class="small">Saving plan: <strong>${money(s.save)}</strong> <button class="textbtn" onclick="adjustSavings()">Adjust</button></div>${bird(sum()===0?'Free places count as real adventures. You choose what makes the day worthwhile.':`Your plan spends ${money(sum())}. That leaves ${money(100-sum())} for your future adventure.`)}<button style="margin-top:14px" class="primary" ${s.plan.length<2?'disabled':''} onclick="depart()">${s.plan.length<2?'Choose '+(2-s.plan.length)+' more stops':'Let’s go!'}</button></aside></div>`;
if(s.stage==='trip'){const a=activities[s.plan[s.trip]],taken=s.photos.includes(a.id);content=`<div class="eyebrow">Your choices, coming to life · Stop ${s.trip+1} of ${s.plan.length}</div><section class="scene" id="scene">${art(a.id)}<div class="pip-trip">${pipMarkup(taken?'happy':'curious')}</div><div class="sceneBadge">${a.name} · ${a.price?money(a.price):'Free to enjoy'}</div><div class="frame" id="frame" aria-label="Camera viewfinder" onpointermove="moveFrame(event)"></div><div class="sceneCaption"><h1>${a.line}</h1><p style="margin-top:12px">${a.moment}</p><div class="tripprogress">${s.plan.map((_,i)=>`<span class="${i<=s.trip?'done':''}"></span>`).join('')}</div></div><div class="sceneActions"><button class="secondary" onclick="snap()">${taken?'✓ Photo saved':'◎ Take a photo'}</button><button class="primary" onclick="nextStop()">${s.trip===s.plan.length-1?'Ride home':'Next stop'}</button></div></section><p class="small" style="margin-top:10px">Move across the viewfinder to frame your memory. Tap “Take a photo” to keep it.</p>`}
if(s.stage==='end'){let left=Math.round((100-sum())*100)/100,achieved=left>=s.initialSave;content=`<section class="finish"><div class="eyebrow">The bus ride home · A pocketful of memories</div><h1>Look at the day you made.</h1><p style="margin-top:12px">${s.photos.length?'Your camera roll tells the story.':'You enjoyed the moments, even without taking photos.'} ${left>0?`And ${money(left)} is coming home with you.`:'You chose to use your full budget today.'}</p><div class="homecoming"><img class="returnphoto" src="assets/bus.webp" alt="Bunny looks through an album on the bus at sunset"><div class="futurecard"><div class="eyebrow">A little closer to next summer</div><img src="assets/europe.webp" alt="Bunny imagines cycling with a cousin in Amsterdam"><h3>${money(left)} for our next adventure</h3><p class="small">${left>0?"Today’s unspent money joins your Europe travel fund. It is one contribution, not the full trip paid for.":"Today you chose to spend your full budget. Your future fund gets no new money from this trip."}</p></div></div><div class="endgrid"><div><div class="album">${s.photos.length?s.photos.map(id=>`<div class="photo">${art(id)}<p>${activities[id].name}</p></div>`).join(''):'<p class="small">No photos this time. Your itinerary is below.</p>'}</div><h3>Your original wishes</h3>${s.wishes.map(id=>`<div class="wishrow"><span>${s.plan.includes(id)?'✓':'○'}</span><span>${activities[id].name}</span><span class="small" style="margin-left:auto">${s.plan.includes(id)?'Made a memory':'Another day'}</span></div>`).join('')}${bird(achieved?`You planned to save ${money(s.initialSave)} and kept ${money(left)}. ${left>0?'That is a contribution to your Europe trip, not the whole trip paid for.':'You followed your plan for today.'}`:`You first planned to save ${money(s.initialSave)}. You kept ${money(left)}, which is ${money(s.initialSave-left)} less. You chose more experiences today and less money for later.`)}</div><aside class="ledger"><div class="eyebrow">Your final receipt</div><h2>It all adds up.</h2><div class="wishrow"><span>Mom’s gift</span><strong>$100</strong></div>${s.plan.map(id=>`<div class="wishrow"><span>${activities[id].name}</span><strong>${money(activities[id].price)}</strong></div>`).join('')}<div class="wishrow total"><span>Spent</span><span>${money(sum())}</span></div><div class="wishrow total"><span>Saved</span><span>${money(left)}</span></div><p class="small" style="margin-top:15px">${money(sum())} spent + ${money(left)} saved = $100</p><div class="bar"><span class="spent" style="width:${sum()}%"></span><span class="saved" style="width:${left}%"></span></div><p class="small" style="margin-top:15px">Unspent money now goes into your future-trip savings.</p></aside></div><div class="actions"><button class="primary" onclick="showLearning()">What did my money do?</button><button class="secondary" onclick="replan()">Try a different day</button></div></section>`}
if(activeMap){activeMap.remove();activeMap=null;}app.innerHTML=`<main class="shell fade">${header()}${content}${footer()}</main>`;initMap();}
function bills(n){return Array.from({length:Math.ceil(n/20)},(_,i)=>`<span class="bill" style="animation-delay:${i*.07}s">$${Math.min(20,n-i*20)}</span>`).join('')}
function setStage(stage){s.stage=stage;render();window.scrollTo(0,0)}function setSavings(n){s.save=n;document.querySelector('#spendmoney').textContent=money(100-n);document.querySelector('#savemoney').textContent=money(n);document.querySelector('#bills').innerHTML=bills(100-n);pipReact('thinking',1100)}function beginPlan(){s.initialSave=s.save;s.plan=[];s.events=[];s.pendingChoice=null;setStage('plan')}
function openModal(html){modal.innerHTML=html;if(!modal.open)modal.showModal()}function closeModal(){modal.close()}function openActivity(id){const a=activities[id],wish=s.stage==='wish',selected=(wish?s.wishes:s.plan).includes(id);openModal(`<div class="preview">${art(id)}<button class="close" onclick="closeModal()" aria-label="Close">×</button></div><div class="modalbody"><span class="price">${wish?a.place:(a.price?money(a.price):'Free')+' · '+a.place}</span><h2>${a.name}</h2><p style="margin-top:10px">${a.line}</p>${!wish&&s.wishes.includes(id)?'<p class="small" style="margin-top:8px">♥ One of your original wishes</p>':''}<div class="actions"><button class="primary" onclick="${wish?'toggleWish':'choose'}(${id})">${selected?'Remove from '+(wish?'wishes':'my day'):wish?'♥ Add to my wishes':'Add to my day'}</button></div></div>`)}
function toggleWish(id){s.wishes=s.wishes.includes(id)?s.wishes.filter(x=>x!==id):[...s.wishes,id];closeModal();render()}
function choose(id){s.pendingChoice=null;if(s.plan.includes(id)){removePlan(id);closeModal();return}if(s.plan.length>=4){openModal(`<div class="modalbody"><h2>A full day already!</h2><p style="margin-top:15px">You have four stops. Remove one from your notebook to make room for this one.</p><div class="actions"><button class="primary" onclick="closeModal()">Back to my plan</button></div></div>`);return}let total=Math.round((sum()+activities[id].price)*100)/100;if(total>100){openModal(`<div class="modalbody"><span class="price">A money trade-off</span><h2>You’re ${money(total-100)} short.</h2>${bird(`This plan would cost ${money(total)}, but you have $100 in total. Even using all your savings won’t cover it.`)}<p style="margin-top:15px">Remove a paid activity from your notebook, or pick a free experience.</p><div class="actions"><button class="primary" onclick="closeModal()">I’ll change my plan</button></div></div>`);return}if(total>100-s.save){let newSave=Math.round((100-total)*100)/100;openModal(`<div class="modalbody"><span class="price">Today or later?</span><h2>You can afford it, with a change.</h2>${bird(`Adding ${activities[id].name} uses ${money(total-(100-s.save))} of the money you set aside. Your saving plan changes from ${money(s.save)} to ${money(newSave)}.`)}<div class="actions"><button class="secondary" onclick="closeModal()">Keep my savings</button><button class="primary" onclick="confirmUseSavings(${id})">Save less & add it</button></div></div>`);return}s.plan.push(id);closeModal();render()}
function confirmUseSavings(id){s.save=Math.round((100-sum()-activities[id].price)*100)/100;s.plan.push(id);closeModal();render()}
function removePlan(id){s.events.push({type:'remove',id,before:[...s.plan]});s.plan=s.plan.filter(x=>x!==id);s.pendingChoice=null;render()}
function adjustSavings(){openModal(`<div class="modalbody"><h2>Make a new saving plan</h2><p style="margin:15px 0">Your current activities leave ${money(100-sum())}. You can reserve any of that for later.</p><label for="newSave">Save: <strong id="newSaveLabel">${money(s.save)}</strong></label><input id="newSave" class="range" type="range" min="0" max="${100-sum()}" step="0.01" value="${s.save}" oninput="document.querySelector('#newSaveLabel').textContent=money(+this.value)"><button class="primary" onclick="recordSavingPlan(+document.querySelector('#newSave').value)">Keep this plan</button></div>`)}
function depart(){if(s.plan.length<2||sum()>100)return;s.trip=0;s.photos=[];setStage('trip')}
function moveFrame(e){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;let r=e.currentTarget.parentElement.getBoundingClientRect();e.currentTarget.style.transform=`translate(${(e.clientX-r.left-r.width/2)*.035}px,${(e.clientY-r.top-r.height/2)*.035}px)`}
function snap(){let id=s.plan[s.trip];if(!s.photos.includes(id))s.photos.push(id);render();document.querySelector('#scene').classList.add('flash');toast('A memory saved to your album.');pipReact('happy',1800)}
function nextStop(){if(s.trip<s.plan.length-1){s.trip++;render()}else setStage('end')}
function toast(text){let d=document.createElement('div');d.className='toast';d.setAttribute('role','status');d.textContent=text;document.body.appendChild(d);setTimeout(()=>d.remove(),2200)}
function showLearning(){openModal(`<div class="modalbody"><div class="eyebrow">A final thought from Pip</div><h2>One budget. Different possibilities.</h2><div class="lesson"><b>Spending buys experiences now.</b>You used ${money(sum())} for the day you chose.</div><div class="lesson"><b>Saving keeps options open for later.</b>You’re setting aside ${money(100-sum())} towards a future trip.</div><div class="lesson"><b>The same money has different uses.</b>$73 could buy the lobster meal, or a $59.85 Duck Tour with $13.15 left. Different purchases buy different experiences. You decide what feels worth it.</div><p class="small">You can enjoy today and plan for tomorrow. There isn’t one perfect split.</p><div class="actions"><button class="primary" onclick="closeModal()">Keep my memories</button></div></div>`)}
function replan(){s.stage='plan';s.trip=0;s.photos=[];s.events=[];s.pendingChoice=null;s.initialSave=s.save;render()}
function restart(){openModal(`<div class="modalbody"><h2>Start a fresh adventure?</h2><p style="margin-top:15px">This will clear this day’s wishes, plan and photos.</p><div class="actions"><button class="secondary" onclick="closeModal()">Keep playing</button><button class="primary" onclick="s=initial();closeModal();render()">Start again</button></div></div>`)}
function priceNote(){openModal(`<div class="modalbody"><h2>Prototype price notes</h2><p style="margin-top:15px">This demo uses our planning figures: whale watching $85.56, whole-lobster meal $73, and an illustrative $7 cannoli. These are not live quotes or verified citywide averages.</p><p style="margin-top:12px">Campus grounds, the Harborwalk and watching boats from the Public Garden are represented as free walks. This simplified prototype assumes travel to Boston and transport between stops are already covered. Any additional taxes or tips are not calculated. Verify final visitor prices before museum use.</p><div class="actions"><button class="primary" onclick="closeModal()">Back to my adventure</button></div></div>`)}
var activeMap=null;
modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});render();
if(document.modelContext?.registerTool){document.modelContext.registerTool({name:'read_boston_game_state',description:'Read the current game stage, wishlist, planned activities and money totals.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({stage:s.stage,wishes:s.wishes.map(id=>activities[id].name),plan:s.plan.map(id=>activities[id].name),spent:sum(),remaining:100-sum(),savingPlan:s.save})})}

function map(){return `<div class="mapwrap"><div id="bostonMap" class="realmap" aria-label="Interactive map of real Boston activity locations"></div><div class="maphelp">Explore the actual places · Zoom in around the waterfront</div><div class="mapchoices">${activities.map(a=>`<button class="mapchoice ${(s.stage==='wish'?s.wishes:s.plan).includes(a.id)?'chosen':''}" onclick="openActivity(${a.id})">${art(a.id)}<span><b>${a.id+1}. ${a.name}</b><small>${s.stage==='wish'?'Take a peek':a.price?money(a.price):'Free'}</small></span></button>`).join('')}</div></div>`}
function initMap(){if(!document.querySelector('#bostonMap'))return;if(typeof L==='undefined'){document.querySelector('#bostonMap').innerHTML='<p class="mapfallback">The map could not load. Explore all seven places below.</p>';return}activeMap=L.map('bostonMap',{scrollWheelZoom:false,zoomControl:true,attributionControl:true}).fitBounds([[42.346,-71.128],[42.385,-71.037]],{padding:[15,15]});let tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>'}).addTo(activeMap);let failures=0;tiles.on('tileerror',()=>{if(++failures===3)toast('Map tiles are unavailable. The experience cards below still work.');});activities.forEach(a=>{let selected=(s.stage==='wish'?s.wishes:s.plan).includes(a.id);let icon=L.divIcon({className:'bunny-marker',html:`<button class="geopin ${selected?'picked':''}" aria-label="${a.name}" title="${a.name}"><img src="assets/${a.image}" alt=""><span>${a.id+1}${selected?' ♥':''}</span></button>`,iconSize:[36,36],iconAnchor:[18,18]});L.marker([a.lat,a.lng],{icon,keyboard:true,title:a.name}).addTo(activeMap).on('click',()=>openActivity(a.id));});}
function setStage(stage){if(stage==='wallet'&&!s.invited){showInvitation();return}s.stage=stage;render();window.scrollTo(0,0)}
function showInvitation(){openModal(`<div class="postcard"><img src="assets/europe.webp" alt="Rabbit cousins cycling along an Amsterdam canal"><div class="modalbody"><div class="eyebrow">A postcard from your cousin · Amsterdam</div><h2>“I’ve already planned our first adventure.”</h2><p style="margin-top:14px">“Next summer, let’s cycle by the canals, share a picnic, and find the best bakery. I can’t wait to see you!”</p><div class="bird">${pipMarkup('curious')}<p>Some money for Boston.<br>Some for a day you’re looking forward to.</p></div><button class="primary" style="width:100%;margin-top:15px" onclick="s.invited=true;closeModal();setStage('wallet')">Let’s open my wallet</button></div></div>`)}
function openActivity(id){const a=activities[id],wish=s.stage==='wish',selected=(wish?s.wishes:s.plan).includes(id);openModal(`<div class="preview">${art(id)}<button class="close" onclick="closeModal()" aria-label="Close">×</button></div><div class="modalbody"><div class="experience-meta"><span class="price">${wish?a.place:(a.price?money(a.price):'Free')}</span><span class="duration">${a.time}</span></div><h2>${a.name}</h2><p style="margin-top:10px">${a.detail}</p><div class="included">${a.includes.map(x=>`<span>✓ ${x}</span>`).join('')}</div>${!wish?`<div class="value-note"><b>What your money buys</b><p>${a.why}</p></div>`:''}${!wish&&s.wishes.includes(id)?'<p class="small" style="margin-top:10px">♥ One of your original wishes</p>':''}<div class="actions"><button class="primary" onclick="${wish?'toggleWish':'choose'}(${id})">${selected?'Remove from '+(wish?'wishes':'my day'):wish?'♥ Add to my wishes':'Add to my day'}</button></div></div>`)}
function commitPlan(ids){const total=Math.round(ids.reduce((n,id)=>n+activities[id].price,0)*100)/100;if(total>100||ids.length>4)return false;const before=[...s.plan],oldSave=s.save,newSave=Math.min(s.save,Math.round((100-total)*100)/100);s.events.push({type:'plan',before,after:[...ids],oldSave,newSave,context:s.pendingChoice?{...s.pendingChoice}:null});s.pendingChoice=null;s.plan=[...ids];s.save=newSave;closeModal();render();pipReact('happy',1600);return true}
function attemptPlan(ids){const total=Math.round(ids.reduce((n,id)=>n+activities[id].price,0)*100)/100;if(total>100||ids.length>4)return false;if(total>100-s.save){let left=Math.round((100-total)*100)/100;openModal(`<div class="modalbody"><div class="eyebrow">Your day, your decision</div><h2>A little more now, a little less later.</h2><div class="savingscompare"><div><strong>${money(s.save)}</strong><span>Planned for Europe</span></div><div><strong>${money(left)}</strong><span>After this change</span></div></div><img class="savepostcard" src="assets/europe.webp" alt="Your future adventure with your cousin">${bird(`This uses ${money(s.save-left)} from your future-trip money. Keep your saving plan, or change it?`, 'thinking')}<div class="actions"><button class="secondary" onclick="closeModal()">Keep my savings</button><button class="primary" onclick='commitPlan(${JSON.stringify(ids)})'>Save less & choose this</button></div></div>`);return false}return commitPlan(ids)}
function choose(id){s.pendingChoice=null;if(s.plan.includes(id)){removePlan(id);closeModal();return}const total=Math.round((sum()+activities[id].price)*100)/100;if(total>100||s.plan.length>=4){showTradeoff(id);return}attemptPlan([...s.plan,id])}
function showTradeoff(id){s.pendingChoice={id,plan:[...s.plan],total:Math.round((sum()+activities[id].price)*100)/100};s.events.push({type:'constraint',...s.pendingChoice});const a=activities[id],total=Math.round((sum()+a.price)*100)/100;const incumbent=[...s.plan].sort((x,y)=>activities[y].price-activities[x].price)[0];const b=activities[incumbent];const options=s.plan.filter(x=>sum()-activities[x].price+a.price<=100);let cheap=activities.filter(x=>!s.plan.includes(x.id)&&x.id!==id&&sum()+x.price<=100).sort((x,y)=>x.price-y.price).slice(0,3);openModal(`<div class="modalbody"><div class="eyebrow">Pip’s choice table</div><h2>${total>100?'Two great wishes. One $100 wallet.':'Four stops make a full day.'}</h2><div class="conflict-total"><span>${money(sum())} planned + ${money(a.price)}</span><strong>${total>100?money(total-100)+' over budget':'Choose a stop to replace'}</strong></div><div class="comparecards"><div>${art(b.id)}<h3>${b.name}</h3><span class="price">${money(b.price)}</span><p>${b.time}</p><button class="secondary" onclick="keepCurrentDay()">Keep my current day</button></div><div>${art(a.id)}<h3>${a.name}</h3><span class="price">${money(a.price)}</span><p>${a.time}</p>${options.includes(b.id)?`<button class="primary" onclick="swapActivity(${b.id},${id})">Choose this instead</button>`:'<span class="small">Swap a stop below</span>'}</div></div>${bird('Your money can buy different experiences. Which one matters more to you?', 'concerned')}${options.filter(x=>x!==b.id).map(x=>`<button class="swapline" onclick="swapActivity(${x},${id})">Replace ${activities[x].name} · Save ${money(100-(sum()-activities[x].price+a.price))} afterwards</button>`).join('')}${cheap.length&&s.plan.length<4?`<h3 style="margin-top:20px;font-size:23px">Or keep your plan and add…</h3><div class="alternatives">${cheap.map(c=>`<button onclick="choose(${c.id})">${art(c.id)}<span>${c.name}<b>${c.price?money(c.price):'Free'}</b></span></button>`).join('')}</div>`:''}<button class="textbtn" style="margin-top:18px" onclick="closeModal()">Back to the map</button></div>`)}
function swapActivity(oldId,newId){s.pendingChoice={...(s.pendingChoice||{}),swapFrom:oldId,id:newId};attemptPlan(s.plan.map(x=>x===oldId?newId:x))}
function confirmUseSavings(id){commitPlan([...s.plan,id])}
function priceNote(){openModal(`<div class="modalbody"><h2>Prices & experience notes</h2><p class="small" style="margin:12px 0">Checked October 7, 2026. Bunny is a 14-year-old student. Published prices are reference prices, not a citywide average or live booking quote.</p>${activities.map(a=>`<div class="sourceitem"><strong>${a.name} · ${money(a.price)}</strong><p>${a.priceBasis}</p>${a.source?`<a href="${a.source}" target="_blank" rel="noopener">Official price information</a>`:''}</div>`).join('')}<p class="small">Whale-watch duration and naturalist narration are based on <a href="https://www.neaq.org/about-us/press-room/press-releases/new-england-aquarium-whale-watch-bhcc-2026/" target="_blank" rel="noopener">Aquarium information</a> and the operator’s tour description. “Allow” times are suggested planning time, not official tour lengths. In this short game, travel and basic meals are already covered; all chosen activities are experienced without schedule conflicts. Prices do not include unlisted extras. Map pins indicate venue areas or departure points, not tour routes.</p><div class="actions"><button class="primary" onclick="closeModal()">Back to my adventure</button></div></div>`)}

// Two short story beats precede the existing wish-map flow.
function renderIntro(){
 if(activeMap){activeMap.remove();activeMap=null;}
 const planning=s.intro===1;
 app.innerHTML=`<main class="shell intro-shell fade">
 <header class="top"><div class="brand">Bunny’s Boston Day</div><button class="textbtn" onclick="setStage('wish')">Skip intro</button></header>
 <section class="intro-story ${planning?'intro-planning':''}" aria-label="${planning?'Planning tomorrow':'Meet Bonnie'}">
 <div class="intro-visual"><img src="assets/intro.webp" alt="Bonnie, a white rabbit, planning a trip at a cozy bedroom desk with a laptop, notebook and packed backpack"><span class="intro-time">The night before · Summer break</span></div>
 <div class="intro-caption" aria-live="polite">
 <div class="eyebrow">${planning?'A notebook full of possibilities':'Meet Bonnie'}</div>
 <h1>${planning?'One day. Where shall we go?':'Tomorrow, Boston!'}</h1>
 <p>${planning?'“I’ll take a peek at the places, then put my favorites in my notebook.”':'School’s out, and Bonnie has a day trip to Boston tomorrow. The backpack is packed. Sleep? Not yet!'}</p>
 <div class="intro-controls"><div class="story-dots" aria-label="Scene ${planning?2:1} of 2"><span class="${planning?'':'current'}"></span><span class="${planning?'current':''}"></span></div>
 <div class="actions">${planning?'<button class="textbtn" onclick="s.intro=0;render()">Back</button>':''}<button class="primary" onclick="${planning?"setStage('wish')":"s.intro=1;render()"}">${planning?'Open my notebook':'Let’s plan tomorrow'}</button></div></div>
 </div></section></main>`;
 window.scrollTo(0,0);
}

function keepCurrentDay(){
 if(s.pendingChoice)s.events.push({type:'keep',...s.pendingChoice});
 s.pendingChoice=null;closeModal();
}
function recordSavingPlan(value){
 const next=Math.max(0,Math.min(value,Math.round((100-sum())*100)/100));
 s.events.push({type:'saving',oldSave:s.save,newSave:next});s.save=next;closeModal();render();
}
function learningCards(){
 const cards=[],left=Math.round((100-sum())*100)/100;
 let choice=[...s.events].reverse().find(e=>e.total>100&&e.type==='keep'&&e.plan.every(id=>s.plan.includes(id))&&!s.plan.includes(e.id)||e.type==='plan'&&e.context?.total>100&&e.context.swapFrom!==undefined&&s.plan.includes(e.context.id)&&!s.plan.includes(e.context.swapFrom));
 if(!choice){const attempted=[...s.events].reverse().find(e=>e.type==='constraint'&&e.total>100&&(s.plan.includes(e.id)?e.plan.some(id=>!s.plan.includes(id)):e.plan.some(id=>s.plan.includes(id))));if(attempted){if(s.plan.includes(attempted.id)){choice={type:'plan',context:{...attempted,swapFrom:attempted.plan.find(id=>!s.plan.includes(id))}}}else{choice={...attempted,type:'keep',plan:attempted.plan.filter(id=>s.plan.includes(id))}}}}
 if(choice){
  const swapped=choice.type==='plan',c=swapped?choice.context:choice;
  const kept=swapped?c.id:[...c.plan].sort((a,b)=>activities[b].price-activities[a].price)[0],givenUp=swapped?c.swapFrom:c.id;
  cards.push({title:'You made a budget trade-off',label:'Budgeting & trade-offs',ids:[kept,givenUp],text:`Adding ${activities[c.id].name} would have made your plan cost ${money(c.total)}. You kept ${activities[kept].name} and left out ${activities[givenUp].name}.`,definition:'A budget allocates limited money. A trade-off means giving up one option to make room for another.',extra:'Opportunity cost is the next-best alternative you give up. Was that the experience you left out?'});
 }else{
  cards.push({title:'You made a plan for limited money',label:'Budgeting',ids:s.plan.slice(0,2),text:`Your $100 covers ${money(sum())} of experiences and leaves ${money(left)} for your future trip.`,definition:'A budget is a plan for how to use your money, including spending and saving.',extra:'Your wishlist and your budget do not have to match. You decide what to prioritize.'});
 }
 const reduction=[...s.events].reverse().find(e=>(e.type==='plan'||e.type==='saving')&&e.newSave<e.oldSave);
 cards.push({title:reduction?'You revised your saving plan':'You kept money for a future goal',label:'Goal-based saving',image:'europe.webp',text:reduction?`During planning, you lowered your saving target from ${money(reduction.oldSave)} to ${money(reduction.newSave)}${reduction.type==='plan'?' to accept a change to your day':''}. After all your choices, you actually saved ${money(left)}.`:`You first aimed to save ${money(s.initialSave)}. At the end, ${money(left)} goes toward your trip with your cousin.`,definition:'Saving means setting money aside for future use. A goal gives that money a purpose.',extra:left===0?'This time, all $100 went to today. Nothing from this gift goes toward the future trip.':'This contributes to the future trip; it does not pay for the whole trip.'});
 const paid=s.plan.find(id=>activities[id].price>0),id=paid===undefined?s.plan[0]:paid,a=activities[id];
 if(a)cards.push({title:'You chose what your money would buy',label:'Value for money',ids:[id],text:`${a.name}: ${a.price?money(a.price):'free'}. ${a.includes.join(' · ')}.`,definition:'Compare what you receive with what you pay. A higher price does not automatically mean more value for you.',extra:a.price?'Think about the experience, what is included, and what matters to you.':'A free experience can still be valuable. Enjoyment does not always require spending.'});
 return cards;
}
function showLearning(index=0){
 const cards=learningCards();s.lessonIndex=Math.max(0,Math.min(index,cards.length-1));const c=cards[s.lessonIndex];
 openModal(`<div class="modalbody personalized"><div class="coach-heading">${pipMarkup(s.lessonIndex===cards.length-1?'farewell':s.lessonIndex===0?'thinking':'idle')}<div><div class="eyebrow">Pip’s recap · ${s.lessonIndex+1} of ${cards.length}</div><span class="small">Your decisions, explained</span></div></div><h2>${c.title}</h2><div class="recap-pictures">${c.image?`<img src="assets/${c.image}" alt="Your future trip">`:(c.ids||[]).map(id=>`<figure>${art(id)}<figcaption>${activities[id].name} · ${money(activities[id].price)}</figcaption></figure>`).join('')}</div><p>${c.text}</p><div class="concept-box"><strong>${c.label}</strong><p>${c.definition}</p></div><p class="small">${c.extra}</p><div class="actions">${s.lessonIndex>0?`<button class="secondary" onclick="showLearning(${s.lessonIndex-1})">Back</button>`:''}${s.lessonIndex<cards.length-1?`<button class="primary" onclick="showLearning(${s.lessonIndex+1})">Next discovery</button>`:'<button class="primary" onclick="closeModal()">Keep my memories</button>'}</div></div>`);
 modal.scrollTop=0;
}
